function detailsFields(d){return `<div class="form-grid">${field('Store name','name',d.name,'text',true,'maxlength="100"')}${field('WhatsApp number (with country code)','whatsapp',d.whatsapp,'tel',true,'placeholder="923001234567"')}<label class="field">Business category<select name="category">${categoryKits.map(k=>k.category).map(c=>`<option ${d.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${field('Your niche (optional)','niche',d.niche||'','text',false,'maxlength="200" placeholder="e.g. women clothing, skincare, bakery"')}<label class="field">Store theme<select name="theme" data-previous-theme="${esc(d.theme||'classic')}">${Object.entries(themes).map(([key,theme])=>`<option value="${key}" ${key===(d.theme||'classic')?'selected':''}>${theme.category} — ${theme.name}</option>`).join('')}</select></label><label class="field">Selling mode<select name="businessMode"><option value="retail" ${!isServiceStore(d)?'selected':''}>Products — cash on delivery</option><option value="enquiry" ${isServiceStore(d)?'selected':''}>Services — WhatsApp enquiry</option></select></label>${field('Fixed delivery charges (PKR)','delivery',d.delivery,'number',true,'min="0" max="100000"')}${field('Logo image URL (optional)','logo',d.logo,'text',false,'placeholder="https://…"')}${field('Banner image URL (optional)','banner',d.banner,'text',false,'placeholder="https://…"')}${field('Brand color','accent',d.accent||'#075e47','color')}${field('Instagram URL (optional)','instagram',d.instagram,'text',false,'inputmode="url" placeholder="instagram.com/yourname"')}${field('Facebook URL (optional)','facebook',d.facebook,'text',false,'inputmode="url" placeholder="facebook.com/yourpage"')}${field('Website URL (optional)','website',d.website,'text',false,'inputmode="url" placeholder="yourwebsite.com"')}</div>${themeSuggestion(d)}${area('About your store','description',d.description)}${area('Business address','address',d.address)}${area('Delivery information','deliveryInfo',d.deliveryInfo)}${area('Returns & exchange policy','returns',d.returns)}<p class="muted">Social links can be entered without https://; we add it automatically. Image links should be public HTTPS URLs. Leave optional fields blank if you’re not ready.</p>`}
const layoutNames=layoutLabels;

function layoutMarkup(type,layout){
  const existing=session.store?.details||draft.details;
  const details={...existing,name:existing.name||'Your store',description:existing.description||'Beautiful products. A store that feels like you.',deliveryInfo:existing.deliveryInfo||'Delivered across Pakistan.',address:existing.address||'Your business address',whatsapp:existing.whatsapp||'923001234567',delivery:Number(existing.delivery)||200};
  const content=(session.store?.sections||draft.sections).find(x=>x.type===type)||{};
  return renderSection({...content,type,layout},details,sampleProductsFor(details));
}
function previewCanvas(type,layout,large=false){return `<div class="layout-preview ${large?'large-layout-preview':''}" aria-hidden="true" inert><div class="preview-canvas storefront" data-theme="${esc((session.store?.details||draft.details).theme||'classic')}" style="${themeStyle(session.store?.details||draft.details)}">${layoutMarkup(type,layout)}</div></div>`;}
function themeStyle(details){const theme=themeForDetails(details);const accent=/^#[a-f0-9]{6}$/i.test(details.accent)?details.accent:theme.accent;return `--brand:${accent};--store-bg:${theme.background};--store-ink:${theme.ink};--store-heading:${theme.typography==='editorial'?'Georgia,serif':theme.typography==='friendly'?'Trebuchet MS,Arial,sans-serif':'Arial,sans-serif'}`;}
function refreshThemeSuggestion(form,auto=false){
 const values=formValues(form),key=themeForNiche(values.category,values.niche);
 const themeSelect=form.querySelector('[name=theme]'),color=form.querySelector('[name=accent]');
 const previous=themeSelect.value;
 const customColor=form.dataset.accentCustom==='true'||color.value!==themes[previous].accent;
 if(auto&&form.dataset.modeCustom!=='true'){const mode=form.querySelector('[name=businessMode]');if(mode)mode.value=key==='digital'?'enquiry':'retail';}if(auto&&form.dataset.themeCustom!=='true'){themeSelect.value=key;themeSelect.dataset.previousTheme=key;form.dataset.activeTheme=key;if(!customColor)color.value=themes[key].accent;}
 const summary=form.querySelector('[data-theme-suggestion]');if(summary)summary.outerHTML=themeSuggestion(values);
}
function suggestedSections(){
 const form=document.querySelector('#editor-form')||document.querySelector('#signup-form');
 const details=session.store?.details||draft.details,key=themeForNiche(details.category,details.niche),preset=themes[key];
 const values=formValues(form),previous=session.store?.sections||draft.sections;
 const selected=preset.sections.map(section=>{const existing=previous.find(s=>s.type===section.type);return {...existing,...section,title:values['title-'+section.type]??existing?.title??'',text:values['text-'+section.type]??existing?.text??'',image:values['image-'+section.type]??existing?.image??'',imageAlt:values['imageAlt-'+section.type]??existing?.imageAlt??'',imagePosition:values['imagePosition-'+section.type]??existing?.imagePosition??'center',mobileImagePosition:values['mobileImagePosition-'+section.type]??existing?.mobileImagePosition??'center'};});
 if(form.id==='signup-form'){draft.sections=selected;draft.sectionsCustomized=true;signup();translatePublic();}
 else{rebuildEditor(selected);toast('Suggested sections selected. Save homepage to apply them.');}
}
