function translatePublic(){if(!roman||!['/','/signup','/login','/forgot-password','/reset-password','/verify-email'].includes(location.pathname))return;const walk=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);const nodes=[];while(walk.nextNode())nodes.push(walk.currentNode);for(const node of nodes){const value=node.textContent.trim();if(translations[value])node.textContent=node.textContent.replace(value,translations[value]);}document.documentElement.lang='en';}
window.addEventListener('pageshow',event=>{if(event.persisted)route();});

let studioDirty=false,studioTimer,studioHistory=[],studioLastState=null,studioLastAccent='';
function recipePicker(d){return `<section class="recipe-picker"><div class="panel-heading"><div><span class="eyebrow">YOUR STARTING POINT</span><h3>Start with a complete look</h3><p class="muted">${esc(themeForDetails(d).category)} · 5 coordinated homepage styles. Customize any section afterwards.</p></div></div><div class="recipe-grid">${homepageRecipes.map((r,i)=>`<button type="button" class="recipe-card" data-recipe="${i}">${previewCanvas('hero',i+1)}<b>${r.name}</b><small>${r.description}</small><span>Preview homepage →</span></button>`).join('')}</div></section>`;}
function sectionImageFields(s){return `<div class="section-photo-controls">${field('Section image URL (optional)','image-'+s.type,s.image||'','text',false,'placeholder="Upload your own or choose a library photo"')}${uploadControl('image-'+s.type)}<div class="photo-actions"><button type="button" class="btn secondary small" data-stock-for="${s.type}">Free photo library</button><button type="button" class="link-btn" data-clear-photo="${s.type}">Use theme image</button></div><div class="form-grid">${field('Image description','imageAlt-'+s.type,s.imageAlt||'')}<label class="field">Desktop crop focus<select name="imagePosition-${s.type}">${['center','top','bottom','left','right'].map(p=>`<option ${s.imagePosition===p?'selected':''}>${p}</option>`).join('')}</select></label><label class="field">Mobile crop focus<select name="mobileImagePosition-${s.type}">${['center','top','bottom','left','right'].map(p=>`<option ${(s.mobileImagePosition||s.imagePosition||'center')===p?'selected':''}>${p}</option>`).join('')}</select></label></div></div>`;}
function editorState(){const form=document.querySelector('#editor-form');if(!form)return null;const v=formValues(form),order=session.store.sections.map(x=>x.type);return readSections(form).map(s=>({...s,title:v['title-'+s.type]??s.title??'',text:v['text-'+s.type]??s.text??'',image:v['image-'+s.type]??s.image??'',imageAlt:v['imageAlt-'+s.type]??s.imageAlt??'',imagePosition:v['imagePosition-'+s.type]??s.imagePosition??'center',mobileImagePosition:v['mobileImagePosition-'+s.type]??s.mobileImagePosition??s.imagePosition??'center'})).sort((a,b)=>(order.includes(a.type)?order.indexOf(a.type):99)-(order.includes(b.type)?order.indexOf(b.type):99));}
function studioSnapshot(){const state=editorState();if(!state)return;const accent=document.querySelector('#editor-form [name=accent]')?.value||'';if(studioLastState&&(JSON.stringify(state)!==JSON.stringify(studioLastState)||accent!==studioLastAccent)){studioHistory.push({sections:studioLastState,accent:studioLastAccent});if(studioHistory.length>30)studioHistory.shift();}studioLastState=structuredClone(state);studioLastAccent=accent;}
function renderStudioPreview(){const target=document.querySelector('#studio-preview-canvas');if(!target)return;target.innerHTML=(editorState()||session.store.sections).map(s=>renderSection(s,{...session.store.details,accent:document.querySelector('#editor-form [name=accent]')?.value||session.store.details.accent})).join('');target.style.cssText=themeStyle({...session.store.details,accent:document.querySelector('#editor-form [name=accent]')?.value||session.store.details.accent});target.querySelectorAll('a,button,input,select,textarea').forEach(el=>el.inert=true);target.querySelectorAll('[data-section]').forEach(section=>{const heading=section.querySelector('[data-section-heading]');if(heading){heading.contentEditable='plaintext-only';heading.setAttribute('aria-label','Edit '+sectionNames[section.dataset.section]+' heading');}if(['hero','about','offers','reviews','featured','categories'].includes(section.dataset.section)){const paragraph=section.querySelector('[data-section-text]');if(paragraph){paragraph.contentEditable='plaintext-only';paragraph.setAttribute('aria-label','Edit section text');}}});const wrap=target.parentElement;const width=wrap.classList.contains('mobile-preview')?390:1200;target.style.width=width+'px';target.style.transform=`scale(${Math.min(1,wrap.clientWidth/width)})`;wrap.style.height=Math.ceil(target.offsetHeight*Math.min(1,wrap.clientWidth/width))+'px';}
function launchChecklist(s){const d=s.details;return [{label:'Business name and WhatsApp',done:Boolean(d.name&&d.whatsapp),tab:'settings'},{label:'Add your brand logo',done:Boolean(d.logo),tab:'settings',optional:true},{label:'Add your first product',done:products.length>0,tab:'products'},{label:'Personalize your homepage',done:s.sections.length>0,tab:'editor'},{label:'Verify your account email',done:session.user.emailVerified,action:'resend-verification'},{label:'Store approval',done:s.status==='approved',tab:'overview'}];}
function enhanceDashboard(){const main=document.querySelector('.workspace-main');if(!main||session.user?.role!=='owner')return;const s=session.store,hasDraft=s.published_details&&(JSON.stringify(s.details)!==s.published_details||JSON.stringify(s.sections)!==s.published_sections);
 main.querySelector('.workspace-header').insertAdjacentHTML('afterend',`<div class="publish-bar"><div><b>${hasDraft?'Unpublished changes':'Your design workspace'}</b><small id="save-status">${s.draft_saved_at?'Draft saved '+new Date(s.draft_saved_at).toLocaleString()+' · ':''}${s.published_at?'Last published '+new Date(s.published_at).toLocaleString():'Save a draft, preview it, then publish.'} · Products and orders update immediately.</small></div><div><a class="btn secondary small" href="/s/${esc(s.slug)}?published=1" target="_blank" rel="noopener">View published</a><button class="btn secondary small" type="button" data-action="launch-check">Launch check</button><button class="btn small" type="button" data-action="publish-store">Publish changes</button></div></div>`);
 if(tab==='overview'){main.querySelector('.stats').insertAdjacentHTML('beforebegin',`<section class="panel launch-checklist"><span class="eyebrow">LET’S GET YOU OPEN</span><h3>Your store setup</h3>${launchChecklist(s).map(c=>`<button class="checklist-item" ${c.action?`data-action="${c.action}"`:`data-tab="${c.tab}"`}><span>${c.done?'✓':'○'}</span><b>${c.label}${c.optional?' (optional)':''}</b><small>${c.done?'Done':'Open →'}</small></button>`).join('')}<button class="btn secondary small" data-action="share-store">Share link & QR code</button></section>`);}
 if(tab==='settings'){document.querySelector('#settings-form').insertAdjacentHTML('beforeend',`<details class="seo-settings"><summary>Google & sharing settings</summary>${field('Page title','seoTitle',s.details.seoTitle||'')}${area('Page description','seoDescription',s.details.seoDescription||'')}${field('Share image URL','shareImage',s.details.shareImage||'')}${uploadControl('shareImage')}${field('Favicon URL','favicon',s.details.favicon||'')}${uploadControl('favicon')}<p class="muted">These appear when your public store is indexed or shared. Search engines choose when to update their preview.</p></details>`);}
 if(tab==='editor'){const form=document.querySelector('#editor-form');form.insertAdjacentHTML('afterbegin',`<div class="studio-toolbar"><span class="badge">DESIGN STUDIO</span><button type="button" class="link-btn" data-action="undo-design">Undo</button><button type="button" class="link-btn" data-action="restore-design">Restore published design</button><span id="studio-save-state">Saved draft</span></div>${field('Brand color','accent',s.details.accent||'#075e47','color')}<details class="studio-preview-panel" open><summary>Live page preview — click a heading to edit</summary><div class="preview-tools"><button type="button" class="btn secondary small" data-device="desktop">Desktop</button><button type="button" class="btn secondary small" data-device="mobile">Mobile</button></div><div class="studio-preview-wrap"><div id="studio-preview-canvas" class="storefront preview-canvas" data-theme="${esc(s.details.theme||'classic')}" style="${themeStyle(s.details)}"></div></div></details>`);studioHistory=[];studioLastState=editorState();studioLastAccent=s.details.accent||'#075e47';requestAnimationFrame(renderStudioPreview);}
}
function studioModal(title,body,cls=''){document.querySelector('.modal-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="panel modal ${cls}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="panel-heading"><h2>${esc(title)}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Close">×</button></div>${body}</div></div>`);}
function recipeSections(index){const source=session.store?.sections||draft.sections,profile=themeForDetails(session.store?.details||draft.details);return profile.sections.map((s,i)=>({...s,...(source.find(x=>x.type===s.type)||{}),layout:homepageRecipes[index].layouts[Object.keys(sectionNames).indexOf(s.type)]}));}
async function studioAction(el,a){
 if(el.dataset.productDetails){const product=products.find(p=>p.id===el.dataset.productDetails)?.details;if(!product)return true;studioModal(product.name,`${product.images?.[0]?`<img src="${esc(product.images[0])}" alt="${esc(product.imageAlt||product.name)}">`:''}<p class="product-detail-price">${money(product.salePrice??product.price)}</p><p>${esc(product.description||'Ask the business for further details.')}</p><p class="muted">${esc(product.category||'')}</p>`,'product-details-modal');return true;}
 if(el.dataset.productPhoto){const item=products.find(p=>p.id===el.dataset.productPhoto);const image=item?.details.images[Number(el.dataset.photoIndex)];if(image){const card=el.closest('.store-product');card.querySelector('.product-media img').src=image;card.querySelectorAll('[data-product-photo]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));}return true;}
 if(a==='clear-category'){filterStoreCategory(el.closest('.storefront'),'');return true;}
 if(el.dataset.fixTab){document.querySelector('.modal-backdrop')?.remove();tab=el.dataset.fixTab;await dashboard();return true;}
 if(el.dataset.recipe!==undefined){const index=Number(el.dataset.recipe),d=session.store?.details||draft.details,sections=recipeSections(index);studioModal(homepageRecipes[index].name+' homepage',`<p class="muted">Illustrative photos and sample products. Your business content stays editable.</p><div class="layout-preview large-layout-preview" inert><div class="preview-canvas storefront" data-theme="${esc(d.theme||'classic')}" style="${themeStyle(d)}">${sections.map(s=>renderSection(s,{...d,name:d.name||'Your store'},sampleProductsFor(d))).join('')}</div></div><button type="button" class="btn full" data-apply-recipe="${index}">Use this homepage</button>`,'layout-modal');return true;}
 if(el.dataset.applyRecipe!==undefined){const selected=recipeSections(Number(el.dataset.applyRecipe));document.querySelector('.modal-backdrop').remove();if(session.store){if(studioDirty&&!confirm('Replace section selection and layouts? Your saved draft stays safe until you save.'))return true;session.store.sections=selected;rebuildEditor(selected);}else{draft.sections=selected;draft.sectionsCustomized=true;signup();}toast('Homepage selected. Customize your sections below.');return true;}
 if(el.dataset.stockFor){const type=el.dataset.stockFor;studioModal('Free photo library',`<p class="muted">Illustrative Unsplash stock photos. These do not represent your own products, team or customer endorsements. Replace them with your business photos before launch where appropriate.</p><label class="field">Find a category<input id="stock-search" placeholder="Search categories"></label><div class="stock-grid">${categoryKits.map(k=>`<button type="button" data-photo-key="${k.id}" data-photo-target="${type}" data-photo-category="${esc(k.category.toLowerCase())}"><img src="${stockImage(k.id,360)}" alt="${esc(k.alt)}" loading="lazy"><b>${esc(k.category)}</b></button>`).join('')}</div><p><a href="https://unsplash.com/license" target="_blank" rel="noopener">Unsplash license →</a> · Check appropriate use; stock images are not business endorsements.</p>`,'layout-modal');return true;}
 if(el.dataset.photoKey){const form=document.querySelector('#editor-form'),key=el.dataset.photoKey,type=el.dataset.photoTarget;form.querySelector(`[name="image-${type}"]`).value=stockImage(key);form.querySelector(`[name="imageAlt-${type}"]`).value=categoryKits.find(k=>k.id===key).alt;document.querySelector('.modal-backdrop').remove();markStudioDirty();return true;}
 if(el.dataset.clearPhoto){const f=document.querySelector('#editor-form');f.querySelector(`[name="image-${el.dataset.clearPhoto}"]`).value='';f.querySelector(`[name="imageAlt-${el.dataset.clearPhoto}"]`).value='';markStudioDirty();return true;}
 if(el.dataset.device){const wrap=document.querySelector('.studio-preview-wrap');wrap.classList.toggle('mobile-preview',el.dataset.device==='mobile');renderStudioPreview();return true;}
 if(a==='undo-design'){const previous=studioHistory.pop();if(!previous){toast('No earlier edit on this screen.');return true;}rebuildEditor(previous.sections,false);document.querySelector('#editor-form [name=accent]').value=previous.accent;studioLastState=structuredClone(previous.sections);studioLastAccent=previous.accent;markStudioDirty(false);return true;}
 if(a==='restore-design'){if(!confirm('Discard the saved design draft and restore the published version? Products and orders stay unchanged.'))return true;await api('/api/store/discard','POST',{});studioDirty=false;await dashboard();toast('Published design restored.');return true;}
 if(a==='launch-check'||a==='publish-store'){if(studioDirty){errorToast('Save your changes before checking or publishing.');return true;}if(a==='publish-store'){el.disabled=true;try{const result=await api('/api/store/publish','POST',{});await dashboard();toast(result.message);}finally{el.disabled=false;}return true;}
 const s=session.store,checks=launchChecklist(s);const warnings=[];if(!s.details.description)warnings.push('Add your own business description.');if(products.some(p=>!p.details.images.length))warnings.push('Some products need their own photographs.');if(!s.details.returns)warnings.push('Add your returns and exchange policy.');if(s.sections.some(x=>x.type==='reviews'&&!x.text))warnings.push('Reviews is an invitation only. Add genuine feedback with permission or remove the section.');if(!s.details.banner&&s.details.theme!=='classic')warnings.push('Your theme uses illustrative stock photography. Confirm it suits your business.');studioModal('Before you launch',`<div class="launch-checklist">${checks.map(c=>`<div class="checklist-item"><span>${c.done?'✓':'○'}</span><b>${c.label}${c.optional?' (optional)':''}</b>${!c.done&&c.tab?`<button type="button" class="link-btn" data-fix-tab="${c.tab}">Fix →</button>`:''}</div>`).join('')}</div>${warnings.map(w=>`<p class="notice">${esc(w)}</p>`).join('')}<p class="muted">Check image rights, links and your mobile preview. Approval and email verification remain required for a new public store.</p>`);return true;}
 if(a==='share-store'){const url=location.origin+'/s/'+session.store.slug;studioModal('Share your dukan',`<p>${esc(url)}</p><div id="store-qr"></div><div class="quick-actions"><button type="button" class="btn secondary" data-action="copy-link">Copy link</button><a class="btn" href="https://wa.me/?text=${encodeURIComponent(url)}" target="_blank" rel="noopener">Share on WhatsApp</a><button type="button" class="btn secondary" data-action="download-qr">Download QR</button></div><p class="muted">The store stays private until approved.</p>`);const {default:qr}=await import('/qrcode.js');const code=qr(0,'M');code.addData(url);code.make();document.querySelector('#store-qr').innerHTML=code.createSvgTag({cellSize:5,margin:4,scalable:true});return true;}
 if(a==='download-qr'){const svg=document.querySelector('#store-qr svg');const blob=new Blob([svg.outerHTML],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=session.store.slug+'-qr.svg';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return true;}
 return false;
}
function rebuildEditor(sections,remember=true){const form=document.querySelector('#editor-form');if(!form)return;if(remember)studioSnapshot();session.store.sections=structuredClone(sections);form.querySelector('.section-picker').outerHTML=sectionPicker(sections);form.querySelector('.section-order').innerHTML=sectionOrderMarkup(sections);form.querySelectorAll('.section-content').forEach(el=>el.remove());const button=form.querySelector('.editor-save');button.insertAdjacentHTML('beforebegin',sections.map(s=>`<div class="section-content"><h3>${sectionNames[s.type]}</h3>${field('Custom heading','title-'+s.type,s.title)}${area('Custom text','text-'+s.type,s.text)}${sectionImageFields(s)}</div>`).join(''));markStudioDirty(remember);}
function markStudioDirty(remember=true){studioDirty=true;if(remember)studioSnapshot();const status=document.querySelector('#studio-save-state')||document.querySelector('#save-status');if(status)status.textContent='Unsaved changes';clearTimeout(studioTimer);studioTimer=setTimeout(renderStudioPreview,160);}
document.addEventListener('input',e=>{const inline=e.target.closest('#studio-preview-canvas [contenteditable]');if(inline){const type=inline.closest('[data-section]').dataset.section,name=(inline.matches('h1,h2')?'title-':'text-')+type,field=document.querySelector(`[name="${name}"]`);if(field){field.value=inline.textContent;studioDirty=true;studioSnapshot();document.querySelector('#studio-save-state').textContent='Unsaved changes';}return;}if(e.target.id==='stock-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-photo-category]').forEach(b=>b.hidden=!b.dataset.photoCategory.includes(q));}if(e.target.closest('#editor-form,#settings-form'))markStudioDirty();});
document.addEventListener('change',e=>{if(e.target.closest('#editor-form,#settings-form')){if(e.target.name?.startsWith('section-')){const type=e.target.name.slice(8),form=e.target.form;if(e.target.checked&&!form.querySelector(`[name="title-${type}"]`)){form.querySelector('.editor-save').insertAdjacentHTML('beforebegin',`<div class="section-content"><h3>${sectionNames[type]}</h3>${field('Custom heading','title-'+type)}${area('Custom text','text-'+type)}${sectionImageFields({type})}</div>`);}}markStudioDirty();}});
document.addEventListener('click',e=>{const heading=e.target.closest('#studio-preview-canvas h1,#studio-preview-canvas h2');if(!heading){const image=e.target.closest('#studio-preview-canvas .kit-media');if(image){const type=image.closest('[data-section]')?.dataset.section;const target=document.querySelector(`[name="image-${type}"]`);target?.scrollIntoView({behavior:'smooth',block:'center'});target?.focus();}return;}const type=heading.closest('[data-section]')?.dataset.section,field=document.querySelector(`[name="title-${type}"]`);if(field){heading.focus();}});
document.addEventListener('focusout',e=>{if(e.target.matches('#studio-preview-canvas [contenteditable]'))markStudioDirty();});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('#studio-preview-canvas h1,#studio-preview-canvas h2')){e.preventDefault();e.target.blur();}if(e.key==='Escape')document.querySelector('.modal-backdrop')?.remove();});
window.addEventListener('beforeunload',event=>{if(studioDirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('resize',()=>{if(document.querySelector('#studio-preview-canvas'))renderStudioPreview();});
document.addEventListener('error',event=>{if(event.target.matches?.('.kit-media img,.stock-grid img')){event.target.closest('figure,button')?.classList.add('photo-unavailable');event.target.alt='Image temporarily unavailable.';}},true);
async function optimizedUpload(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose a JPEG, PNG or WebP photo.');if(file.size>15*1024*1024)throw Error('Choose an image under 15 MB.');const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>40_000_000)throw Error('This photo is too large. Resize it first.');const ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/webp',.82).split(',')[1];return {type:'image/webp',data};}finally{bitmap.close();}}

function templateGallery(){app.innerHTML=`${nav()}<main class="template-gallery"><div class="gallery-intro"><span class="eyebrow">THE TEMPLATE COLLECTION</span><h1>A beautiful start.<br><em>For your kind of business.</em></h1><p>30 categories. Five coordinated homepage styles. Five layouts for every section. No design experience needed.</p><label class="field">Find your business<input id="gallery-search" placeholder="Try bakery, fashion, plants…"></label></div><div class="gallery-grid">${categoryKits.map(k=>`<article class="gallery-card" data-gallery-category="${esc(k.category.toLowerCase())}"><img src="${stockImage(k.id,600)}" alt="${esc(k.alt)}" loading="lazy"><div><small>${esc(k.category)}</small><h2>${esc(k.name)}</h2><p>${esc(k.heading)}</p><div class="theme-swatches"><span style="background:${k.accent}"></span><span style="background:${themes[k.id].background}"></span></div><div class="gallery-actions"><a class="btn secondary small" href="/demo?kit=${k.id}&layout=4" target="_blank" rel="noopener">Preview store →</a><a class="btn small" href="/signup?kit=${k.id}">Start with this theme →</a></div></div></article>`).join('')}</div><p class="muted">Photography is illustrative stock imagery. Your store can use your own photos, text and brand colors. Digital services currently use WhatsApp ordering; automatic file delivery and booking are not included.</p></main>`;}
document.addEventListener('input',event=>{if(event.target.id==='gallery-search'){const query=event.target.value.toLowerCase();document.querySelectorAll('[data-gallery-category]').forEach(card=>card.hidden=!card.dataset.galleryCategory.includes(query));}});

function filterStoreCategory(root,category){if(!root)return;const section=root.querySelector('[data-section=featured]');if(!section)return;let count=0;section.querySelectorAll('.store-product').forEach(card=>{card.hidden=Boolean(category)&&card.dataset.productCategory!==category;if(!card.hidden)count++;});const status=section.querySelector('.product-filter-status');status.hidden=!category;status.querySelector('span').textContent=category+' · '+count+' matching items';section.querySelector('.product-count').textContent=count+' '+(isServiceStore(currentStore?.details)?'services':'products');root.querySelectorAll('[data-filter-category]').forEach(a=>{if(category&&a.dataset.filterCategory===category)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');});section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
document.addEventListener('click',e=>{const link=e.target.closest('[data-filter-category]');if(!link||link.closest('.layout-preview,#studio-preview-canvas'))return;e.preventDefault();filterStoreCategory(link.closest('.storefront'),link.dataset.filterCategory);});

route();
